import Spreadsheet from "./spreadsheet"

export default function Page() {
  return (
    <div className="px-4 py-10 md:px-6 md:py-14">
      <Spreadsheet />
    </div>
  )
}

"use client"

import { ChevronDown, Menu, Plus } from "lucide-react"

import { cn } from "@/lib/utils"

import { Cursor } from "./components/cursor"
import {
  COLUMN_HEADERS,
  DATA_COLUMN_COUNT,
  EDIT_CELL,
  VISIBLE_COLS,
  VISIBLE_ROW_COUNT,
  type RowData,
} from "./lib/config"
import { useSpreadsheetAnimation } from "./hooks/use-spreadsheet-animation"

import "./styles/spreadsheet.css"

function cellValue(
  dataIdx: number,
  colIdx: number,
  rows: readonly RowData[],
  editDisplay: string,
  editingThisCell: boolean,
): string {
  if (colIdx >= DATA_COLUMN_COUNT) return ""
  const row = rows[dataIdx]
  if (!row) return ""

  const values = [
    row.account,
    row.arr,
    row.growth,
    row.marketValue,
    row.gainLoss,
  ] as const
  if (editingThisCell) return editDisplay
  return values[colIdx] ?? ""
}

export default function Spreadsheet({ className }: { className?: string }) {
  const {
    pressed,
    isSelected,
    isEditing,
    isTsmTyping,
    tsmShowsSelectionChrome,
    tsmFocusCol,
    commitFlash,
    syncRowVisible,
    rows,
    cellRef,
    formulaPrefix,
    formulaValue,
    showFormulaArea,
    editDisplay,
    cursorVisible,
    cursor,
    activeCol,
    activeRow,
  } = useSpreadsheetAnimation()

  const colTemplate = `1.75rem repeat(${VISIBLE_COLS.length}, minmax(0, 1fr))`
  const rowTemplate = `1.5rem repeat(${VISIBLE_ROW_COUNT}, 1.375rem)`
  const emptyRowCount = Math.max(0, VISIBLE_ROW_COUNT - 1 - rows.length)

  return (
    <div
      className={cn(
        "ss-root ss-shell mx-auto w-full min-w-0 max-w-3xl overflow-hidden rounded-md",
        className,
      )}
    >
      <div className="ss-formula">
        <div className="ss-name-box">
          <span className="tabular-nums">
            {showFormulaArea ? cellRef : " "}
          </span>
          <ChevronDown className="ss-name-box-chevron size-3 shrink-0" aria-hidden />
        </div>
        <div className="ss-formula-sep" aria-hidden />
        <span className="ss-fx" aria-hidden>
          fx
        </span>
        <div className="ss-formula-input">
          {showFormulaArea ? (
            <>
              {`${formulaPrefix}${formulaValue}`}
              {isEditing || isTsmTyping ? (
                <span className="ss-caret" aria-hidden />
              ) : null}
            </>
          ) : null}
        </div>
      </div>

      <div className="ss-grid-wrap">
        <div className="ss-grid-body">
          <div
            className="ss-grid"
            style={{
              gridTemplateColumns: colTemplate,
              gridTemplateRows: rowTemplate,
            }}
          >
            <div className="ss-corner" aria-hidden />

            {VISIBLE_COLS.map((letter, colIdx) => (
              <div
                key={letter}
                className={cn(
                  "ss-col-header",
                  activeCol === colIdx && "ss-col-header--active",
                )}
              >
                {letter}
              </div>
            ))}

            <div className="contents">
              <div className="ss-row-num">1</div>
              {VISIBLE_COLS.map((letter, colIdx) => (
                <div
                  key={`hdr-${letter}`}
                  className={cn(
                    "ss-cell ss-cell--header",
                    (colIdx === 1 ||
                      colIdx === 2 ||
                      colIdx === 3 ||
                      colIdx === 4) &&
                      "ss-cell--num",
                  )}
                >
                  <span className="truncate">{COLUMN_HEADERS[colIdx] ?? ""}</span>
                </div>
              ))}
            </div>

            {rows.map((row, dataIdx) => {
              const sheetRow = dataIdx + 2
              const isSyncRow = syncRowVisible && row.id === "r4"

              return (
                <div key={row.id} className="contents">
                  <div
                    className={cn(
                      "ss-row-num",
                      activeRow === dataIdx && "ss-row-num--active",
                    )}
                  >
                    {sheetRow}
                  </div>

                  {VISIBLE_COLS.map((letter, colIdx) => {
                    const selected =
                      isSelected &&
                      dataIdx === EDIT_CELL.row &&
                      colIdx === EDIT_CELL.col
                    const editingThisCell = Boolean(isEditing && selected)
                    const isTsmSelectedCell =
                      tsmShowsSelectionChrome &&
                      isSyncRow &&
                      tsmFocusCol !== null &&
                      colIdx === tsmFocusCol
                    const raw = cellValue(
                      dataIdx,
                      colIdx,
                      rows,
                      editDisplay,
                      editingThisCell,
                    )
                    const display =
                      raw &&
                      (colIdx === 1 || colIdx === 3)
                        ? `$${raw}`
                        : raw

                    return (
                      <div
                        key={`${row.id}-${letter}`}
                        className={cn(
                          "ss-cell-wrap",
                          selected && commitFlash && "ss-cell--commit-flash",
                        )}
                      >
                        <div
                          className={cn(
                            "ss-cell",
                            (colIdx === 1 ||
                              colIdx === 2 ||
                              colIdx === 3 ||
                              colIdx === 4) &&
                              "ss-cell--num",
                            colIdx === 4 &&
                              raw.startsWith("+") &&
                              "ss-cell--pnl-pos",
                            colIdx === 4 &&
                              raw.startsWith("-") &&
                              "ss-cell--pnl-neg",
                          )}
                        >
                          <span className="truncate">{display}</span>
                        </div>
                        {selected ? (
                          <>
                            <div className="ss-active-border" aria-hidden />
                            <div className="ss-fill-handle" aria-hidden />
                          </>
                        ) : null}
                        {isTsmSelectedCell ? (
                          <>
                            <div className="ss-active-border" aria-hidden />
                            <div className="ss-fill-handle" aria-hidden />
                          </>
                        ) : null}
                      </div>
                    )
                  })}
                </div>
              )
            })}

            {Array.from({ length: emptyRowCount }, (_, i) => {
              const sheetRow = rows.length + 2 + i
              return (
                <div key={`empty-${sheetRow}`} className="contents">
                  <div className="ss-row-num">{sheetRow}</div>
                  {VISIBLE_COLS.map((letter) => (
                    <div key={`${sheetRow}-${letter}`} className="ss-cell" />
                  ))}
                </div>
              )
            })}
          </div>

          {cursorVisible ? (
            <Cursor x={cursor.x} y={cursor.y} pressed={pressed} />
          ) : null}
        </div>
      </div>

      <div className="ss-sheet-bar" role="toolbar" aria-label="Sheet tabs">
        <button type="button" className="ss-sheet-bar-btn" aria-label="Add sheet">
          <Plus className="size-3.5" strokeWidth={2} aria-hidden />
        </button>
        <button type="button" className="ss-sheet-bar-btn" aria-label="All sheets">
          <Menu className="size-3.5" strokeWidth={2} aria-hidden />
        </button>
        <button type="button" className="ss-sheet-tab" aria-current="page">
          <span>Positions</span>
          <ChevronDown className="ss-sheet-tab-chevron size-3 shrink-0" aria-hidden />
        </button>
      </div>
    </div>
  )
}

"use client"

import { MousePointer2 } from "lucide-react"

import { cn } from "@/lib/utils"

type CursorProps = {
  x: number
  y: number
  pressed?: boolean
  className?: string
}

export function Cursor({ x, y, pressed, className }: CursorProps) {
  return (
    <MousePointer2
      aria-hidden
      strokeWidth={2}
      className={cn(
        "pointer-events-none absolute z-20 size-3.5",
        "fill-foreground stroke-background text-foreground",
        "[paint-order:stroke_fill]",
        "motion-safe:transition-[left,top,transform] motion-safe:duration-500 motion-safe:ease-out",
        className,
      )}
      style={{
        left: `${x}%`,
        top: `${y}%`,
        transform: `translate(-2px, -2px)${pressed ? " scale(0.92)" : ""}`,
      }}
    />
  )
}

"use client"

import { useEffect, useState } from "react"

import {
  EDIT_CELL,
  EDIT_FROM,
  EDIT_TO,
  EMPTY_TSM_ROW,
  INITIAL_ROWS,
  PHASE_NEXT_MAP,
  SPREADSHEET_CURSOR,
  SYNC_ROW,
  TIMING,
  TSM_CURSOR_BY_COL,
  TSM_DATA_ROW_INDEX,
  TSM_GL_FORMULA,
  TSM_MKT_FORMULA,
  VISIBLE_COLS,
  isTsmFormulaTypingPhase,
  isTsmTypingPhase,
  tsmPhaseColumn,
  tsmShowsCellChrome,
  tsmShowsFormula,
  type RowData,
  type SpreadsheetPhase,
} from "../lib/config"

const TSM_VALUE_KEYS = ["account", "arr", "growth"] as const

/** Matches TIMING field cadence in config (`TSM_CHAR_MS`). */
const TSM_CHAR_MS = 132

function parseUsd(s: string): number {
  return Number.parseFloat(s.replace(/,/g, ""))
}

function parsePctSigned(s: string): number {
  return Number.parseFloat(s.trim().replace(/%/g, "")) / 100
}

function formatUsdMv(priceStr: string, qtyStr: string): string {
  const mv = Number.parseFloat(priceStr) * Number.parseInt(qtyStr, 10)
  return mv.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })
}

function formatGainLossPct(decimal: number): string {
  const pct = decimal * 100
  const sign = pct >= 0 ? "+" : ""
  return `${sign}${pct.toFixed(1)}%`
}

export function useSpreadsheetAnimation(active = true) {
  const [phase, setPhase] = useState<SpreadsheetPhase>("setup")
  const [typed, setTyped] = useState(0)
  const [pressed, setPressed] = useState(false)
  const [commitFlash, setCommitFlash] = useState(false)
  const [tsmDraft, setTsmDraft] = useState<RowData>(() => ({
    ...EMPTY_TSM_ROW,
  }))
  const [tsmFormulaTyping, setTsmFormulaTyping] = useState("")

  useEffect(() => {
    if (!active) {
      setPhase("setup")
      return
    }
    const t = setTimeout(() => setPhase(PHASE_NEXT_MAP[phase]), TIMING[phase])
    return () => clearTimeout(t)
  }, [active, phase])

  useEffect(() => {
    if (!active) return

    if (phase === "setup" || phase === "resetting") {
      setTyped(0)
      setPressed(false)
      setCommitFlash(false)
      setTsmDraft({ ...EMPTY_TSM_ROW })
      setTsmFormulaTyping("")
      return
    }

    if (phase === "tsmPrep") {
      setTyped(EDIT_TO.length)
      setTsmDraft({ ...EMPTY_TSM_ROW })
      setTsmFormulaTyping("")
      return
    }

    if (phase === "select") {
      setPressed(true)
      const t = setTimeout(() => setPressed(false), 180)
      return () => clearTimeout(t)
    }

    if (phase === "typing") {
      setTyped(0)
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= EDIT_TO.length; i++) {
        timers.push(setTimeout(() => setTyped(i), 120 + i * 165))
      }
      return () => timers.forEach(clearTimeout)
    }

    if (phase === "commit") {
      setTyped(EDIT_TO.length)
      setCommitFlash(true)
      const t = setTimeout(() => setCommitFlash(false), 480)
      return () => clearTimeout(t)
    }

    if (phase === "tsmType0" || phase === "tsmType1" || phase === "tsmType2") {
      setTyped(EDIT_TO.length)
      setPressed(true)
      const unpress = setTimeout(() => setPressed(false), 180)
      setTsmFormulaTyping("")

      const colMap: Partial<Record<SpreadsheetPhase, number>> = {
        tsmType0: 0,
        tsmType1: 1,
        tsmType2: 2,
      }
      const col = colMap[phase] ?? 0
      const key = TSM_VALUE_KEYS[col]
      const target = SYNC_ROW[key]
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= target.length; i++) {
        timers.push(
          setTimeout(() => {
            setTsmDraft((d) => ({
              ...d,
              [key]: target.slice(0, i),
            }))
          }, 155 + i * TSM_CHAR_MS),
        )
      }
      return () => {
        clearTimeout(unpress)
        timers.forEach(clearTimeout)
      }
    }

    if (phase === "tsmType3") {
      setTyped(EDIT_TO.length)
      setPressed(true)
      const unpress = setTimeout(() => setPressed(false), 180)
      setTsmFormulaTyping("")
      const target = TSM_MKT_FORMULA
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= target.length; i++) {
        timers.push(
          setTimeout(() => {
            setTsmFormulaTyping(target.slice(0, i))
          }, 155 + i * TSM_CHAR_MS),
        )
      }
      const finalize = setTimeout(() => {
        setTsmDraft((d) => ({
          ...d,
          marketValue: SYNC_ROW.marketValue,
        }))
        setTsmFormulaTyping(target)
      }, 155 + target.length * TSM_CHAR_MS + 40)
      return () => {
        clearTimeout(unpress)
        timers.forEach(clearTimeout)
        clearTimeout(finalize)
      }
    }

    if (phase === "tsmType4") {
      setTyped(EDIT_TO.length)
      setPressed(true)
      const unpress = setTimeout(() => setPressed(false), 180)
      setTsmFormulaTyping("")
      const target = TSM_GL_FORMULA
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= target.length; i++) {
        timers.push(
          setTimeout(() => {
            setTsmFormulaTyping(target.slice(0, i))
          }, 155 + i * TSM_CHAR_MS),
        )
      }
      const finalize = setTimeout(() => {
        setTsmDraft((d) => ({
          ...d,
          gainLoss: SYNC_ROW.gainLoss,
        }))
        setTsmFormulaTyping(target)
      }, 155 + target.length * TSM_CHAR_MS + 40)
      return () => {
        clearTimeout(unpress)
        timers.forEach(clearTimeout)
        clearTimeout(finalize)
      }
    }

    if (
      phase === "tsmMove0" ||
      phase === "tsmMove1" ||
      phase === "tsmMove2" ||
      phase === "tsmMove3" ||
      phase === "tsmMove4"
    ) {
      setTyped(EDIT_TO.length)
      if (phase === "tsmMove4") {
        setTsmFormulaTyping("")
      }
      return
    }

    if (phase === "holding") {
      setTyped(EDIT_TO.length)
      setTsmFormulaTyping("")
      setTsmDraft({ ...SYNC_ROW })
    }
  }, [active, phase])

  const isEditing = phase === "typing" || phase === "commit"

  const isSelected = phase === "select" || phase === "typing" || phase === "commit"

  const isTsmTyping = isTsmTypingPhase(phase)

  const editCommitted =
    phase === "commit" ||
    (phase.startsWith("tsm") && phase !== "resetting") ||
    phase === "holding"

  const editDisplay = isEditing ? EDIT_TO.slice(0, typed) : EDIT_FROM

  const baseRows = INITIAL_ROWS.map((row, i) => {
    if (i !== EDIT_CELL.row) return row
    if (!editCommitted) return row
    const impliedCost =
      parseUsd(row.marketValue) / (1 + parsePctSigned(row.gainLoss))
    const newMvNum = Number.parseFloat(EDIT_TO) * Number.parseInt(row.growth, 10)
    return {
      ...row,
      arr: EDIT_TO,
      marketValue: formatUsdMv(EDIT_TO, row.growth),
      gainLoss: formatGainLossPct((newMvNum - impliedCost) / impliedCost),
    }
  })

  const syncRowVisible =
    phase === "tsmPrep" ||
    phase.startsWith("tsmMove") ||
    phase.startsWith("tsmType") ||
    phase === "holding"

  const rows = syncRowVisible ? [...baseRows, tsmDraft] : baseRows

  const tsmCol = tsmPhaseColumn(phase)

  let cellRef: string
  let formulaPrefix: string
  let formulaValue: string

  if (tsmShowsFormula(phase)) {
    const sheetRow = TSM_DATA_ROW_INDEX + 2
    const col =
      phase === "tsmPrep" ? 0 : tsmCol !== null ? tsmCol : 0
    cellRef = `${VISIBLE_COLS[col]}${sheetRow}`
    const movePhase =
      phase === "tsmMove0" ||
      phase === "tsmMove1" ||
      phase === "tsmMove2" ||
      phase === "tsmMove3" ||
      phase === "tsmMove4"

    if (isTsmFormulaTypingPhase(phase)) {
      formulaPrefix = ""
      formulaValue = tsmFormulaTyping
    } else {
      const draftVals = [
        tsmDraft.account,
        tsmDraft.arr,
        tsmDraft.growth,
        tsmDraft.marketValue,
        tsmDraft.gainLoss,
      ] as const
      formulaPrefix = col === 1 ? "$" : ""
      formulaValue =
        phase === "tsmPrep" || movePhase ? "" : draftVals[col] ?? ""
    }
  } else {
    cellRef = `${VISIBLE_COLS[EDIT_CELL.col]}${EDIT_CELL.row + 2}`
    formulaPrefix = "$"
    formulaValue = isEditing ? editDisplay : EDIT_FROM
  }

  const showFormulaArea =
    isSelected || isEditing || tsmShowsFormula(phase)

  const cursorVisible =
    phase === "cursorMove" ||
    phase === "select" ||
    phase === "typing" ||
    phase === "commit" ||
    phase === "tsmPrep" ||
    phase.startsWith("tsmMove") ||
    phase.startsWith("tsmType")

  const cursor = (() => {
    if (phase === "cursorMove") return SPREADSHEET_CURSOR.approach
    if (phase === "tsmPrep") return SPREADSHEET_CURSOR.intelPrep
    if (tsmCol !== null) return TSM_CURSOR_BY_COL[tsmCol]
    return SPREADSHEET_CURSOR.cell
  })()

  let activeCol: number
  let activeRow: number

  if (tsmShowsCellChrome(phase) && tsmCol !== null) {
    activeCol = tsmCol
    activeRow = TSM_DATA_ROW_INDEX
  } else if (isSelected) {
    activeCol = EDIT_CELL.col
    activeRow = EDIT_CELL.row
  } else {
    activeCol = -1
    activeRow = -1
  }

  return {
    phase,
    pressed,
    isSelected,
    isEditing,
    isTsmTyping,
    commitFlash,
    syncRowVisible,
    tsmShowsSelectionChrome: tsmShowsCellChrome(phase),
    rows,
    cellRef,
    formulaPrefix,
    formulaValue,
    showFormulaArea,
    editDisplay,
    cursorVisible,
    cursor,
    activeCol,
    activeRow,
    tsmFocusCol: tsmCol,
  }
}

/**
 * Spreadsheet animation — semiconductor positions:
 * revise Intel price target → add TSM row (typed inputs + Excel-style formulas for value & return).
 */

export type SpreadsheetPhase =
  | "setup"
  | "cursorMove"
  | "select"
  | "typing"
  | "commit"
  | "tsmPrep"
  | "tsmMove0"
  | "tsmType0"
  | "tsmMove1"
  | "tsmType1"
  | "tsmMove2"
  | "tsmType2"
  | "tsmMove3"
  | "tsmType3"
  | "tsmMove4"
  | "tsmType4"
  | "holding"
  | "resetting"

const PHASE_NEXT: Record<SpreadsheetPhase, SpreadsheetPhase> = {
  setup: "cursorMove",
  cursorMove: "select",
  select: "typing",
  typing: "commit",
  commit: "tsmPrep",
  tsmPrep: "tsmMove0",
  tsmMove0: "tsmType0",
  tsmType0: "tsmMove1",
  tsmMove1: "tsmType1",
  tsmType1: "tsmMove2",
  tsmMove2: "tsmType2",
  tsmType2: "tsmMove3",
  tsmMove3: "tsmType3",
  tsmType3: "tsmMove4",
  tsmMove4: "tsmType4",
  tsmType4: "holding",
  holding: "resetting",
  resetting: "setup",
}

export const PHASE_NEXT_MAP = PHASE_NEXT

/** Character cadence + padding so phase timers outlive typing timers. */
const TSM_CHAR_MS = 132
const TSM_TYPE_PAD = 360

/** Visible data columns A–E; F–H stay blank in the mock. */
export const DATA_COLUMN_COUNT = 5 as const

/** Row shape — TSM row uses Excel row 5 in formulas (`B5`, `C5`, `D5`). */
export type RowData = {
  id: string
  account: string
  arr: string
  growth: string
  marketValue: string
  gainLoss: string
}

/** 0-based Intel row — price cell edited before TSM sync. */
export const EDIT_CELL = { row: 2, col: 1 }

/** Prior print → today’s price (Illustrative — align with `INITIAL_ROWS` INTC row.) */
export const EDIT_FROM = "107.95"
export const EDIT_TO = "108.77"

/**
 * Early/core: NVDA, INTC — larger % vs average cost.
 * Later tranches: AMD (underwater top-up), then TSM row (new starter line).
 */
export const INITIAL_ROWS: readonly RowData[] = [
  {
    id: "r1",
    account: "NVDA",
    arr: "225.32",
    growth: "38",
    marketValue: "8,562.16",
    gainLoss: "+245.3%",
  },
  {
    id: "r2",
    account: "AMD",
    arr: "424.10",
    growth: "12",
    marketValue: "5,089.20",
    gainLoss: "-7.8%",
  },
  {
    id: "r3",
    account: "INTC",
    arr: EDIT_FROM,
    growth: "85",
    marketValue: "9,175.75",
    gainLoss: "+52.1%",
  },
]

/** Newer TSM line — shares typed; value & % from formulas vs cost. */
export const SYNC_ROW: RowData = {
  id: "r4",
  account: "TSM",
  arr: "404.35",
  growth: "9",
  marketValue: "3,639.15",
  gainLoss: "+6.4%",
}

export const TSM_MKT_FORMULA = "=B5*C5" as const
/** Cost basis $3,420 — later buy; ~+6.4% vs `D5` at `404.35` × 9 shares. */
export const TSM_GL_FORMULA = "=(D5-3420)/3420" as const

function tsmValueTypeMs(len: number): number {
  return 170 + len * TSM_CHAR_MS + TSM_TYPE_PAD
}

function tsmFormulaTypeMs(formula: string): number {
  return 170 + formula.length * TSM_CHAR_MS + TSM_TYPE_PAD
}

export const TIMING: Record<SpreadsheetPhase, number> = {
  setup: 700,
  cursorMove: 900,
  select: 400,
  typing: 1400,
  commit: 600,
  tsmPrep: 400,
  tsmMove0: 660,
  tsmType0: tsmValueTypeMs(SYNC_ROW.account.length),
  tsmMove1: 640,
  tsmType1: tsmValueTypeMs(SYNC_ROW.arr.length),
  tsmMove2: 620,
  tsmType2: tsmValueTypeMs(SYNC_ROW.growth.length),
  tsmMove3: 620,
  tsmType3: tsmFormulaTypeMs(TSM_MKT_FORMULA),
  tsmMove4: 620,
  tsmType4: tsmFormulaTypeMs(TSM_GL_FORMULA),
  holding: 3000,
  resetting: 400,
}

export const VISIBLE_COLS = ["A", "B", "C", "D", "E", "F", "G", "H"] as const
export const VISIBLE_ROW_COUNT = 8

/** Column labels rendered in sheet row 1 (A–E); F–H blank in UI. */
export const COLUMN_HEADERS = [
  "Symbol",
  "Price",
  "Quantity",
  "Market value",
  "Gain/Loss",
] as const

/** Appended sync row index in `rows` when visible (sheet row = index + 2). */
export const TSM_DATA_ROW_INDEX = 3

/** Empty placeholders until each cell is filled. */
export const EMPTY_TSM_ROW: RowData = {
  id: "r4",
  account: "",
  arr: "",
  growth: "",
  marketValue: "",
  gainLoss: "",
}

/** Matches `gridTemplateColumns` in spreadsheet.tsx (`1.75rem` + 8× `1fr`). */
const GRID_ROW_NUM_REM = 1.75
const GRID_DATA_COL_COUNT = VISIBLE_COLS.length
/** `max-w-3xl` sheet width — keeps cursor anchors aligned at default block size. */
const GRID_REF_WIDTH_REM = 48

/** Horizontal center of a 0-based data column as % of `.ss-grid-body` width. */
export function gridColumnCenterPercent(colIdx: number): number {
  const flexCol = (GRID_REF_WIDTH_REM - GRID_ROW_NUM_REM) / GRID_DATA_COL_COUNT
  const centerRem = GRID_ROW_NUM_REM + colIdx * flexCol + flexCol / 2
  return Math.round((centerRem / GRID_REF_WIDTH_REM) * 100)
}

const GRID_COL_LETTER_ROW_REM = 1.5
const GRID_SHEET_HEADER_ROW_REM = 1.375
const GRID_DATA_ROW_REM = 1.375

/** Vertical center of a 0-based data row as % of `.ss-grid-body` height. */
export function gridDataRowCenterPercent(dataRowIdx: number): number {
  const totalRem =
    GRID_COL_LETTER_ROW_REM +
    GRID_SHEET_HEADER_ROW_REM +
    VISIBLE_ROW_COUNT * GRID_DATA_ROW_REM
  const topRem =
    GRID_COL_LETTER_ROW_REM +
    GRID_SHEET_HEADER_ROW_REM +
    dataRowIdx * GRID_DATA_ROW_REM
  const centerRem = topRem + GRID_DATA_ROW_REM / 2
  return Math.round((centerRem / totalRem) * 100)
}

const TSM_ROW_CURSOR_Y = gridDataRowCenterPercent(TSM_DATA_ROW_INDEX)

/** Cursor anchor % inside `.ss-grid-body` — column centers on TSM sheet row. */
export const TSM_CURSOR_BY_COL = [
  { x: gridColumnCenterPercent(0), y: TSM_ROW_CURSOR_Y },
  { x: gridColumnCenterPercent(1), y: TSM_ROW_CURSOR_Y },
  { x: gridColumnCenterPercent(2), y: TSM_ROW_CURSOR_Y },
  { x: gridColumnCenterPercent(3), y: TSM_ROW_CURSOR_Y },
  { x: gridColumnCenterPercent(4), y: TSM_ROW_CURSOR_Y },
] as const

/** 0-based column during TSM move/type phases (null during prep / non-TSM). */
export function tsmPhaseColumn(phase: SpreadsheetPhase): number | null {
  const map: Partial<Record<SpreadsheetPhase, number>> = {
    tsmMove0: 0,
    tsmType0: 0,
    tsmMove1: 1,
    tsmType1: 1,
    tsmMove2: 2,
    tsmType2: 2,
    tsmMove3: 3,
    tsmType3: 3,
    tsmMove4: 4,
    tsmType4: 4,
  }
  return map[phase] ?? null
}

export function isTsmTypingPhase(phase: SpreadsheetPhase): boolean {
  return (
    phase === "tsmType0" ||
    phase === "tsmType1" ||
    phase === "tsmType2" ||
    phase === "tsmType3" ||
    phase === "tsmType4"
  )
}

/** True while a formula is being “typed” in the formula bar (mkt / G·L columns). */
export function isTsmFormulaTypingPhase(phase: SpreadsheetPhase): boolean {
  return phase === "tsmType3" || phase === "tsmType4"
}

/** Selection chrome on the active TSM cell (move + type). */
export function tsmShowsCellChrome(phase: SpreadsheetPhase): boolean {
  return tsmPhaseColumn(phase) !== null
}

/** Formula bar reflects TSM activity (prep shows destination A5 empty). */
export function tsmShowsFormula(phase: SpreadsheetPhase): boolean {
  return (
    phase === "tsmPrep" ||
    phase === "tsmMove0" ||
    phase === "tsmType0" ||
    phase === "tsmMove1" ||
    phase === "tsmType1" ||
    phase === "tsmMove2" ||
    phase === "tsmType2" ||
    phase === "tsmMove3" ||
    phase === "tsmType3" ||
    phase === "tsmMove4" ||
    phase === "tsmType4"
  )
}

/** Cursor % relative to `.ss-grid-body`. */
export const SPREADSHEET_CURSOR = {
  approach: { x: 26, y: 48 },
  cell: { x: gridColumnCenterPercent(EDIT_CELL.col), y: 54 },
  /** Gain/Loss column (E) on Intel row — hand-off before adding TSM. */
  intelPrep: { x: gridColumnCenterPercent(4), y: 54 },
} as const

/* spreadsheet — Google Sheets grid mock (light / dark via .dark ancestor) */

.ss-root {
  --ss-shell-bg: #ffffff;
  --ss-border: #dadce0;
  --ss-shadow: 0 1px 2px rgb(60 64 67 / 0.3), 0 2px 6px 2px rgb(60 64 67 / 0.15);
  --ss-formula-bg: #ffffff;
  --ss-formula-border: #e0e0e0;
  --ss-name-box-fg: #3c4043;
  --ss-name-box-border: #dadce0;
  --ss-fx-fg: #70757a;
  --ss-grid-bg: #ffffff;
  --ss-header-bg: #f8f9fa;
  --ss-header-fg: #70757a;
  --ss-header-active: #d2e3fc;
  --ss-grid-line: #e0e0e0;
  --ss-cell-fg: #3c4043;
  --ss-cell-muted: #70757a;
  --ss-selection: #1a73e8;
  --ss-selection-fill: #ffffff;
  --ss-commit-flash: rgb(26 115 232 / 0.1);
  --ss-caret: #3c4043;
  --ss-sheet-bar-bg: #f8f9fa;
  --ss-sheet-bar-border: #dadce0;
  --ss-sheet-bar-icon: #5f6368;
  --ss-sheet-tab-bg: #e8f0fe;
  --ss-sheet-tab-fg: #1a73e8;
}

.dark .ss-root {
  --ss-shell-bg: #202124;
  --ss-border: #5f6368;
  --ss-shadow: 0 1px 3px rgb(0 0 0 / 0.4), 0 4px 12px rgb(0 0 0 / 0.35);
  --ss-formula-bg: #202124;
  --ss-formula-border: #5f6368;
  --ss-name-box-fg: #e8eaed;
  --ss-name-box-border: #5f6368;
  --ss-fx-fg: #9aa0a6;
  --ss-grid-bg: #202124;
  --ss-header-bg: #292a2d;
  --ss-header-fg: #9aa0a6;
  --ss-header-active: #394457;
  --ss-grid-line: #3c4043;
  --ss-cell-fg: #e8eaed;
  --ss-cell-muted: #9aa0a6;
  --ss-selection: #8ab4f8;
  --ss-selection-fill: #202124;
  --ss-commit-flash: rgb(138 180 248 / 0.14);
  --ss-caret: #e8eaed;
  --ss-sheet-bar-bg: #292a2d;
  --ss-sheet-bar-border: #5f6368;
  --ss-sheet-bar-icon: #9aa0a6;
  --ss-sheet-tab-bg: #394457;
  --ss-sheet-tab-fg: #8ab4f8;
}

.ss-shell {
  border: 1px solid var(--ss-border);
  background-color: var(--ss-shell-bg);
  box-shadow: var(--ss-shadow);
  font-family: Arial, Roboto, "Helvetica Neue", sans-serif;
}

/* ── Formula bar ── */

.ss-formula {
  display: flex;
  height: 1.75rem;
  align-items: stretch;
  border-bottom: 1px solid var(--ss-formula-border);
  background-color: var(--ss-formula-bg);
}

.ss-name-box {
  display: flex;
  width: 3.25rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 0.125rem;
  border-right: 1px solid var(--ss-formula-border);
  padding: 0 0.25rem;
  font-size: 11px;
  color: var(--ss-name-box-fg);
}

.ss-name-box-chevron {
  color: var(--ss-cell-muted);
}

.ss-formula-sep {
  width: 1px;
  flex-shrink: 0;
  background-color: var(--ss-formula-border);
}

.ss-fx {
  display: flex;
  width: 1.75rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 12px;
  font-style: italic;
  color: var(--ss-fx-fg);
}

.ss-formula-input {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  padding: 0 0.5rem;
  font-size: 11px;
  color: var(--ss-cell-fg);
}

/* ── Grid ── */

.ss-grid-wrap {
  background-color: var(--ss-grid-bg);
}

.ss-grid {
  display: grid;
  width: 100%;
}

.ss-corner {
  background-color: var(--ss-header-bg);
  border-right: 1px solid var(--ss-grid-line);
  border-bottom: 1px solid var(--ss-grid-line);
}

.ss-col-header,
.ss-row-num {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--ss-header-bg);
  color: var(--ss-header-fg);
  font-size: 11px;
  user-select: none;
}

.ss-col-header {
  border-right: 1px solid var(--ss-grid-line);
  border-bottom: 1px solid var(--ss-grid-line);
}

.ss-row-num {
  border-right: 1px solid var(--ss-grid-line);
  border-bottom: 1px solid var(--ss-grid-line);
}

.ss-col-header--active,
.ss-row-num--active {
  background-color: var(--ss-header-active);
  color: var(--ss-name-box-fg);
}

.ss-cell-wrap {
  position: relative;
  height: 100%;
  min-height: 0;
  min-width: 0;
}

.ss-cell {
  display: flex;
  height: 100%;
  align-items: center;
  overflow: hidden;
  border-right: 1px solid var(--ss-grid-line);
  border-bottom: 1px solid var(--ss-grid-line);
  background-color: var(--ss-grid-bg);
  padding: 0 0.375rem;
  font-size: 11px;
  color: var(--ss-cell-fg);
}

.ss-cell--num {
  justify-content: flex-end;
  font-variant-numeric: tabular-nums;
}

.ss-cell--muted {
  color: var(--ss-cell-muted);
}

.ss-cell--header {
  background-color: var(--ss-header-bg);
  font-size: 10px;
  font-weight: 600;
  color: var(--ss-name-box-fg);
}

.ss-cell--pnl-pos {
  color: #137333;
}

.dark .ss-cell--pnl-pos {
  color: #81c995;
}

.ss-cell--pnl-neg {
  color: #c5221f;
}

.dark .ss-cell--pnl-neg {
  color: #f28b82;
}

.ss-active-border {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 2;
  border: 2px solid var(--ss-selection);
  margin: -1px;
}

.ss-fill-handle {
  pointer-events: none;
  position: absolute;
  right: -5px;
  bottom: -5px;
  z-index: 3;
  height: 6px;
  width: 6px;
  border: 1px solid var(--ss-selection-fill);
  background-color: var(--ss-selection);
}

.ss-cell--commit-flash .ss-cell {
  animation: ss-commit-flash 0.5s ease-out both;
}

@keyframes ss-commit-flash {
  0% {
    background-color: var(--ss-commit-flash);
  }
  100% {
    background-color: var(--ss-grid-bg);
  }
}

.ss-caret {
  display: inline-block;
  width: 1px;
  height: 0.9em;
  margin-left: 1px;
  vertical-align: text-bottom;
  background-color: var(--ss-caret);
  animation: ss-caret-blink 1.1s step-start infinite;
}

@keyframes ss-caret-blink {
  0%,
  49.9% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

.ss-grid-body {
  position: relative;
  overflow: hidden;
}

.ss-grid-body::-webkit-scrollbar {
  display: none;
}

/* ── Sheet tab bar ── */

.ss-sheet-bar {
  display: flex;
  height: 1.875rem;
  align-items: center;
  gap: 0.125rem;
  border-top: 1px solid var(--ss-sheet-bar-border);
  background-color: var(--ss-sheet-bar-bg);
  padding: 0 0.25rem;
}

.ss-sheet-bar-btn {
  display: flex;
  height: 1.5rem;
  width: 1.5rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 2px;
  background: transparent;
  color: var(--ss-sheet-bar-icon);
  cursor: default;
}

.ss-sheet-tab {
  display: flex;
  height: 1.5rem;
  align-items: center;
  gap: 0.25rem;
  border: none;
  border-radius: 2px 2px 0 0;
  background-color: var(--ss-sheet-tab-bg);
  padding: 0 0.5rem 0 0.625rem;
  font-size: 11px;
  font-weight: 600;
  color: var(--ss-sheet-tab-fg);
  cursor: default;
}

.ss-sheet-tab-chevron {
  color: var(--ss-sheet-tab-fg);
}
